INSERT INTO daily_verses (reference, text, theme, translation) VALUES
-- STRENGTH (18 verses)
('Isaiah 40:31', 'But those who trust in the LORD will find new strength. They will soar high on wings like eagles. They will run and not grow weary. They will walk and not faint.', 'strength', 'NLT'),
('Philippians 4:13', 'For I can do everything through Christ, who gives me strength.', 'strength', 'NLT'),
('Psalm 46:1', 'God is our refuge and strength, always ready to help in times of trouble.', 'strength', 'NLT'),
('2 Corinthians 12:9', 'Each time he said, "My grace is all you need. My power works best in weakness."', 'strength', 'NLT'),
('Deuteronomy 31:6', 'So be strong and courageous! Do not be afraid and do not panic before them. For the LORD your God will personally go ahead of you. He will neither fail you nor abandon you.', 'strength', 'NLT'),
('Psalm 73:26', 'My health may fail, and my spirit may grow weak, but God remains the strength of my heart; he is mine forever.', 'strength', 'NLT'),
('Isaiah 41:10', 'Don''t be afraid, for I am with you. Don''t be discouraged, for I am your God. I will strengthen you and help you. I will hold you up with my victorious right hand.', 'strength', 'NLT'),
('Nehemiah 8:10', 'And Nehemiah continued, "Go and celebrate with a feast of rich foods and sweet drinks, and share gifts of food with people who have nothing prepared. This is a sacred day before our Lord. Don''t be dejected and sad, for the joy of the LORD is your strength!"', 'strength', 'NLT'),
('Psalm 18:32', 'God arms me with strength, and he makes my way perfect.', 'strength', 'NLT'),
('Psalm 27:1', 'The LORD is my light and my salvation — so why should I be afraid? The LORD is my fortress, protecting me from danger, so why should I tremble?', 'strength', 'NLT'),
('Psalm 28:7', 'The LORD is my strength and shield. I trust him with all my heart. He helps me, and my heart is filled with joy. I burst out in songs of thanksgiving.', 'strength', 'NLT'),
('Psalm 29:11', 'The LORD gives his people strength. The LORD blesses them with peace.', 'strength', 'NLT'),
('Psalm 31:24', 'So be strong and courageous, all you who put your hope in the LORD!', 'strength', 'NLT'),
('Psalm 37:39', 'The LORD rescues the godly; he is their fortress in times of trouble.', 'strength', 'NLT'),
('Psalm 68:35', 'God is awesome in his sanctuary. The God of Israel gives power and strength to his people. Praise be to God!', 'strength', 'NLT'),
('Psalm 138:3', 'As soon as I pray, you answer me; you encourage me by giving me strength.', 'strength', 'NLT'),
('Habakkuk 3:19', 'The Sovereign LORD is my strength! He makes me as surefooted as a deer, able to tread upon the heights.', 'strength', 'NLT'),
('Ephesians 6:10', 'A final word: Be strong in the Lord and in his mighty power.', 'strength', 'NLT'),

-- PEACE (18 verses)
('John 14:27', 'I am leaving you with a gift — peace of mind and heart. And the peace I give is a gift the world cannot give. So don''t be troubled or afraid.', 'peace', 'NLT'),
('Philippians 4:6-7', 'Don''t worry about anything; instead, pray about everything. Tell God what you need, and thank him for all he has done. Then you will experience God''s peace, which exceeds anything we can understand. His peace will guard your hearts and minds as you live in Christ Jesus.', 'peace', 'NLT'),
('Isaiah 26:3', 'You will keep in perfect peace all who trust in you, all whose thoughts are fixed on you!', 'peace', 'NLT'),
('Romans 8:6', 'So letting your sinful nature control your mind leads to death. But letting the Spirit control your mind leads to life and peace.', 'peace', 'NLT'),
('Psalm 4:8', 'In peace I will lie down and sleep, for you alone, O LORD, will keep me safe.', 'peace', 'NLT'),
('Colossians 3:15', 'And let the peace that comes from Christ rule in your hearts. For as members of one body you are called to live in peace. And always be thankful.', 'peace', 'NLT'),
('Psalm 29:11', 'The LORD gives his people strength. The LORD blesses them with peace.', 'peace', 'NLT'),
('Romans 15:13', 'I pray that God, the source of hope, will fill you completely with joy and peace because you trust in him. Then you will overflow with confident hope through the power of the Holy Spirit.', 'peace', 'NLT'),
('Matthew 5:9', 'God blesses those who work for peace, for they will be called the children of God.', 'peace', 'NLT'),
('Psalm 119:165', 'Those who love your instructions have great peace and do not stumble.', 'peace', 'NLT'),
('Isaiah 9:6', 'For a child is born to us, a son is given to us. The government will rest on his shoulders. And he will be called: Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.', 'peace', 'NLT'),
('John 16:33', 'I have told you all this so that you may have peace in me. Here on earth you will have many trials and sorrows. But take heart, because I have overcome the world.', 'peace', 'NLT'),
('2 Thessalonians 3:16', 'Now may the Lord of peace himself give you his peace at all times and in every situation. The Lord be with you all.', 'peace', 'NLT'),
('Numbers 6:26', 'May the LORD show you his favor and give you his peace.', 'peace', 'NLT'),
('Psalm 34:14', 'Turn away from evil and do good. Search for peace, and work to maintain it.', 'peace', 'NLT'),
('Isaiah 55:12', 'You will live in joy and peace. The mountains and hills will burst into song, and the trees of the field will clap their hands!', 'peace', 'NLT'),
('Romans 5:1', 'Therefore, since we have been made right in God''s sight by faith, we have peace with God because of what Jesus Christ our Lord has done for us.', 'peace', 'NLT'),
('Galatians 5:22', 'But the Holy Spirit produces this kind of fruit in our lives: love, joy, peace, patience, kindness, goodness, faithfulness.', 'peace', 'NLT'),

-- COMFORT (18 verses)
('Psalm 23:4', 'Even when I walk through the darkest valley, I will not be afraid, for you are close beside me. Your rod and your staff protect and comfort me.', 'comfort', 'NLT'),
('2 Corinthians 1:3-4', 'All praise to God, the Father of our Lord Jesus Christ. God is our merciful Father and the source of all comfort. He comforts us in all our troubles so that we can comfort others. When they are troubled, we will be able to give them the same comfort God has given us.', 'comfort', 'NLT'),
('Matthew 11:28', 'Then Jesus said, "Come to me, all of you who are weary and carry heavy burdens, and I will give you rest."', 'comfort', 'NLT'),
('Psalm 34:18', 'The LORD is close to the brokenhearted; he rescues those whose spirits are crushed.', 'comfort', 'NLT'),
('Isaiah 49:13', 'Sing for joy, O heavens! Rejoice, O earth! Burst into song, O mountains! For the LORD has comforted his people and will have compassion on them in their suffering.', 'comfort', 'NLT'),
('Psalm 147:3', 'He heals the brokenhearted and bandages their wounds.', 'comfort', 'NLT'),
('Revelation 21:4', 'He will wipe every tear from their eyes, and there will be no more death or sorrow or crying or pain. All these things are gone forever.', 'comfort', 'NLT'),
('Isaiah 41:13', 'For I hold you by your right hand — I, the LORD your God. And I say to you, "Don''t be afraid. I am here to help you."', 'comfort', 'NLT'),
('Psalm 55:22', 'Give your burdens to the LORD, and he will take care of you. He will not permit the godly to slip and fall.', 'comfort', 'NLT'),
('Romans 8:28', 'And we know that God causes everything to work together for the good of those who love God and are called according to his purpose for them.', 'comfort', 'NLT'),
('Psalm 94:19', 'When doubts filled my mind, your comfort gave me renewed hope and cheer.', 'comfort', 'NLT'),
('Isaiah 66:13', 'I will comfort you there in Jerusalem as a mother comforts her child.', 'comfort', 'NLT'),
('Psalm 30:5', 'For his anger lasts only a moment, but his favor lasts a lifetime! Weeping may last through the night, but joy comes with the morning.', 'comfort', 'NLT'),
('Lamentations 3:22-23', 'The faithful love of the LORD never ends! His mercies never cease. Great is his faithfulness; his mercies begin afresh each morning.', 'comfort', 'NLT'),
('2 Corinthians 4:17', 'For our present troubles are small and won''t last very long. Yet they produce for us a glory that vastly outweighs them and will last forever!', 'comfort', 'NLT'),
('Psalm 71:21', 'You will restore me to even greater honor and comfort me once again.', 'comfort', 'NLT'),
('John 14:1', 'Don''t let your hearts be troubled. Trust in God, and trust also in me.', 'comfort', 'NLT'),
('1 Peter 5:7', 'Give all your worries and cares to God, for he cares about you.', 'comfort', 'NLT'),

-- PRAISE (18 verses)
('Psalm 150:6', 'Let everything that breathes sing praises to the LORD! Praise the LORD!', 'praise', 'NLT'),
('Psalm 100:4', 'Enter his gates with thanksgiving; go into his courts with praise. Give thanks to him and praise his name.', 'praise', 'NLT'),
('Psalm 34:1', 'I will praise the LORD at all times. I will constantly speak his praises.', 'praise', 'NLT'),
('Hebrews 13:15', 'Therefore, let us offer through Jesus a continual sacrifice of praise to God, proclaiming our allegiance to his name.', 'praise', 'NLT'),
('Psalm 145:3', 'Great is the LORD! He is most worthy of praise! No one can measure his greatness.', 'praise', 'NLT'),
('Psalm 9:1-2', 'I will praise you, LORD, with all my heart; I will tell of all the marvelous things you have done. I will be filled with joy because of you. I will sing praises to your name, O Most High.', 'praise', 'NLT'),
('Psalm 95:1', 'Come, let us sing to the LORD! Let us shout joyfully to the Rock of our salvation.', 'praise', 'NLT'),
('Psalm 103:1', 'Let all that I am praise the LORD; with my whole heart, I will praise his holy name.', 'praise', 'NLT'),
('Psalm 113:3', 'Everywhere — from east to west — praise the name of the LORD.', 'praise', 'NLT'),
('Psalm 148:13', 'Let them all praise the name of the LORD. For his name is very great; his glory towers over the earth and heaven!', 'praise', 'NLT'),
('Psalm 96:4', 'Great is the LORD! He is most worthy of praise! He is to be feared above all gods.', 'praise', 'NLT'),
('Psalm 63:3', 'Your unfailing love is better than life itself; how I praise you!', 'praise', 'NLT'),
('Psalm 71:8', 'Let me shout your praises from morning to night.', 'praise', 'NLT'),
('Psalm 135:3', 'Praise the LORD, for the LORD is good; celebrate his lovely name with music.', 'praise', 'NLT'),
('Psalm 42:11', 'Why am I discouraged? Why is my heart so sad? I will put my hope in God! I will praise him again — my Savior and my God!', 'praise', 'NLT'),
('Acts 16:25', 'Around midnight Paul and Silas were praying and singing hymns to God, and the other prisoners were listening.', 'praise', 'NLT'),
('Psalm 150:1', 'Praise the LORD! Praise God in his sanctuary; praise him in his mighty heaven!', 'praise', 'NLT'),
('Psalm 146:1-2', 'Praise the LORD! Let all that I am praise the LORD. I will praise the LORD as long as I live. I will sing praises to my God with my dying breath.', 'praise', 'NLT'),

-- WISDOM (18 verses)
('Proverbs 3:5-6', 'Trust in the LORD with all your heart; do not depend on your own understanding. Seek his will in all you do, and he will show you which path to take.', 'wisdom', 'NLT'),
('James 1:5', 'If you need wisdom, ask our generous God, and he will give it to you. He will not rebuke you for asking.', 'wisdom', 'NLT'),
('Proverbs 4:7', 'Getting wisdom is the wisest thing you can do! And whatever else you do, develop good judgment.', 'wisdom', 'NLT'),
('Psalm 111:10', 'Fear of the LORD is the foundation of true wisdom. All who obey his commandments will grow in wisdom. Praise him forever!', 'wisdom', 'NLT'),
('Proverbs 2:6', 'For the LORD grants wisdom! From his mouth come knowledge and understanding.', 'wisdom', 'NLT'),
('Colossians 3:16', 'Let the message about Christ, in all its richness, fill your lives. Teach and counsel each other with all the wisdom he gives. Sing psalms and hymns and spiritual songs to God with thankful hearts.', 'wisdom', 'NLT'),
('Proverbs 16:16', 'How much better to get wisdom than gold, and good judgment than silver!', 'wisdom', 'NLT'),
('Ecclesiastes 7:12', 'Wisdom and money can get you almost anything, but only wisdom can save your life.', 'wisdom', 'NLT'),
('Proverbs 9:10', 'Fear of the LORD is the foundation of wisdom. Knowledge of the Holy One results in good judgment.', 'wisdom', 'NLT'),
('Proverbs 1:7', 'Fear of the LORD is the foundation of true knowledge, but fools despise wisdom and discipline.', 'wisdom', 'NLT'),
('Proverbs 19:20', 'Get all the advice and instruction you can, so you will be wise the rest of your life.', 'wisdom', 'NLT'),
('Proverbs 11:2', 'Pride leads to disgrace, but with humility comes wisdom.', 'wisdom', 'NLT'),
('Proverbs 3:13', 'Joyful is the person who finds wisdom, the one who gains understanding.', 'wisdom', 'NLT'),
('James 3:17', 'But the wisdom from above is first of all pure. It is also peace loving, gentle at all times, and willing to yield to others. It is full of mercy and the fruit of good deeds. It shows no favoritism and is always sincere.', 'wisdom', 'NLT'),
('Proverbs 24:14', 'In the same way, wisdom is sweet to your soul. If you find it, you will have a bright future, and your hopes will not be cut short.', 'wisdom', 'NLT'),
('Proverbs 12:15', 'Fools think their own way is right, but the wise listen to others.', 'wisdom', 'NLT'),
('Psalm 90:12', 'Teach us to realize the brevity of life, so that we may grow in wisdom.', 'wisdom', 'NLT'),
('1 Corinthians 1:30', 'God has united you with Christ Jesus. For our benefit God made him to be wisdom itself. Christ made us right with God; he made us pure and holy, and he freed us from sin.', 'wisdom', 'NLT'),

-- HOPE (19 verses)
('Romans 15:13', 'I pray that God, the source of hope, will fill you completely with joy and peace because you trust in him. Then you will overflow with confident hope through the power of the Holy Spirit.', 'hope', 'NLT'),
('Jeremiah 29:11', '"For I know the plans I have for you," says the LORD. "They are plans for good and not for disaster, to give you a future and a hope."', 'hope', 'NLT'),
('Romans 8:24-25', 'We were given this hope when we were saved. (If we already have something, we don''t need to hope for it. But if we look forward to something we don''t yet have, we must wait patiently and confidently.)', 'hope', 'NLT'),
('Psalm 62:5', 'Let all that I am wait quietly before God, for my hope is in him.', 'hope', 'NLT'),
('Hebrews 6:19', 'This hope is a strong and trustworthy anchor for our souls. It leads us through the curtain into God''s inner sanctuary.', 'hope', 'NLT'),
('Psalm 39:7', 'And so, Lord, where do I put my hope? My only hope is in you.', 'hope', 'NLT'),
('Psalm 71:5', 'O Lord, you alone are my hope. I''ve trusted you, O LORD, from childhood.', 'hope', 'NLT'),
('Romans 5:5', 'And this hope will not lead to disappointment. For we know how dearly God loves us, because he has given us the Holy Spirit to fill our hearts with his love.', 'hope', 'NLT'),
('1 Peter 1:3', 'All praise to God, the Father of our Lord Jesus Christ. It is by his great mercy that we have been born again, because God raised Jesus Christ from the dead. Now we live with great expectation.', 'hope', 'NLT'),
('Psalm 130:5', 'I am counting on the LORD; yes, I am counting on him. I have put my hope in his word.', 'hope', 'NLT'),
('Isaiah 40:31', 'But those who trust in the LORD will find new strength. They will soar high on wings like eagles. They will run and not grow weary. They will walk and not faint.', 'hope', 'NLT'),
('Romans 12:12', 'Rejoice in our confident hope. Be patient in trouble, and keep on praying.', 'hope', 'NLT'),
('Psalm 33:18', 'But the LORD watches over those who fear him, those who rely on his unfailing love.', 'hope', 'NLT'),
('Psalm 42:5', 'Why am I discouraged? Why is my heart so sad? I will put my hope in God! I will praise him again — my Savior and my God!', 'hope', 'NLT'),
('Psalm 146:5', 'But joyful are those who have the God of Israel as their helper, whose hope is in the LORD their God.', 'hope', 'NLT'),
('Titus 2:13', 'while we look forward with hope to that wonderful day when the glory of our great God and Savior, Jesus Christ, will be revealed.', 'hope', 'NLT'),
('Hebrews 11:1', 'Faith shows the reality of what we hope for; it is the evidence of things we cannot see.', 'hope', 'NLT'),
('Micah 7:7', 'As for me, I look to the LORD for help. I wait confidently for God to save me, and my God will certainly hear me.', 'hope', 'NLT'),
('Psalm 25:5', 'Lead me by your truth and teach me, for you are the God who saves me. All day long I put my hope in you.', 'hope', 'NLT'),

-- FAITH (18 verses)
('Hebrews 11:1', 'Faith shows the reality of what we hope for; it is the evidence of things we cannot see.', 'faith', 'NLT'),
('Romans 10:17', 'So faith comes from hearing, that is, hearing the Good News about Christ.', 'faith', 'NLT'),
('2 Corinthians 5:7', 'For we live by believing and not by seeing.', 'faith', 'NLT'),
('Matthew 17:20', '"You don''t have enough faith," Jesus told them. "I tell you the truth, if you had faith even as small as a mustard seed, you could say to this mountain, ''Move from here to there,'' and it would move. Nothing would be impossible."', 'faith', 'NLT'),
('Mark 11:24', 'I tell you, you can pray for anything, and if you believe that you''ve received it, it will be yours.', 'faith', 'NLT'),
('Ephesians 2:8-9', 'God saved you by his grace when you believed. And you can''t take credit for this; it is a gift from God. Salvation is not a reward for the good things we have done, so none of us can boast about it.', 'faith', 'NLT'),
('Galatians 2:20', 'My old self has been crucified with Christ. It is no longer I who live, but Christ lives in me. So I live in this earthly body by trusting in the Son of God, who loved me and gave himself for me.', 'faith', 'NLT'),
('James 2:17', 'So you see, faith by itself isn''t enough. Unless it produces good deeds, it is dead and useless.', 'faith', 'NLT'),
('1 John 5:4', 'For every child of God defeats this evil world, and we achieve this victory through our faith.', 'faith', 'NLT'),
('Romans 1:17', 'This Good News tells us how God makes us right in his sight. This is accomplished from start to finish by faith. As the Scriptures say, "It is through faith that a righteous person has life."', 'faith', 'NLT'),
('Mark 9:23', '"What do you mean, ''If I can''?'' Jesus asked. "Anything is possible if a person believes."', 'faith', 'NLT'),
('Hebrews 11:6', 'And it is impossible to please God without faith. Anyone who wants to come to him must believe that God exists and that he rewards those who sincerely seek him.', 'faith', 'NLT'),
('Romans 4:20-21', 'Abraham never wavered in believing God''s promise. In fact, his faith grew stronger, and in this he brought glory to God. He was fully convinced that God is able to do whatever he promises.', 'faith', 'NLT'),
('Matthew 21:22', 'You can pray for anything, and if you have faith, you will receive it.', 'faith', 'NLT'),
('1 Peter 1:7', 'These trials will show that your faith is genuine. It is being tested as fire tests and purifies gold — though your faith is far more precious than mere gold. So when your faith remains strong through many trials, it will bring you much praise and glory and honor on the day when Jesus Christ is revealed to the whole world.', 'faith', 'NLT'),
('Habakkuk 2:4', 'Look at the proud! They trust in themselves, and their lives are crooked. But the righteous will live by their faithfulness to God.', 'faith', 'NLT'),
('Luke 17:6', 'The Lord answered, "If you had faith even as small as a mustard seed, you could say to this mulberry tree, ''May you be uprooted and be planted in the sea,'' and it would obey you!"', 'faith', 'NLT'),
('Hebrews 12:2', 'We do this by keeping our eyes on Jesus, the champion who initiates and perfects our faith. Because of the joy awaiting him, he endured the cross, disregarding its shame. Now he is seated in the place of honor beside God''s throne.', 'faith', 'NLT'),

-- LOVE (19 verses)
('1 Corinthians 13:4-5', 'Love is patient and kind. Love is not jealous or boastful or proud or rude. It does not demand its own way. It is not irritable, and it keeps no record of being wronged.', 'love', 'NLT'),
('John 3:16', 'For this is how God loved the world: He gave his one and only Son, so that everyone who believes in him will not perish but have eternal life.', 'love', 'NLT'),
('1 John 4:19', 'We love each other because he loved us first.', 'love', 'NLT'),
('Romans 8:38-39', 'And I am convinced that nothing can ever separate us from God''s love. Neither death nor life, neither angels nor demons, neither our fears for today nor our worries about tomorrow — not even the powers of hell can separate us from God''s love. No power in the sky above or in the earth below — indeed, nothing in all creation will ever be able to separate us from the love of God that is revealed in Christ Jesus our Lord.', 'love', 'NLT'),
('1 John 4:8', 'But anyone who does not love does not know God, for God is love.', 'love', 'NLT'),
('Jeremiah 31:3', 'Long ago the LORD said to Israel: "I have loved you, my people, with an everlasting love. With unfailing love I have drawn you to myself."', 'love', 'NLT'),
('1 Corinthians 13:13', 'Three things will last forever — faith, hope, and love — and the greatest of these is love.', 'love', 'NLT'),
('1 John 3:18', 'Dear children, let''s not merely say that we love each other; let us show the truth by our actions.', 'love', 'NLT'),
('John 15:13', 'There is no greater love than to lay down one''s life for one''s friends.', 'love', 'NLT'),
('Ephesians 3:17-19', 'Then Christ will make his home in your hearts as you trust in him. Your roots will grow down into God''s love and keep you strong. And may you have the power to understand, as all God''s people should, how wide, how long, how high, and how deep his love is. May you experience the love of Christ, though it is too great to understand fully. Then you will be made complete with all the fullness of life and power that comes from God.', 'love', 'NLT'),
('Deuteronomy 7:9', 'Understand, therefore, that the LORD your God is indeed God. He is the faithful God who keeps his covenant for a thousand generations and lavishes his unfailing love on those who love him and obey his commands.', 'love', 'NLT'),
('Psalm 36:7', 'How precious is your unfailing love, O God! All humanity finds shelter in the shadow of your wings.', 'love', 'NLT'),
('1 Peter 4:8', 'Most important of all, continue to show deep love for each other, for love covers a multitude of sins.', 'love', 'NLT'),
('Song of Solomon 8:7', 'Many waters cannot quench love, nor can rivers drown it. If a man tried to buy love with all his wealth, his offer would be utterly scorned.', 'love', 'NLT'),
('Romans 5:8', 'But God showed his great love for us by sending Christ to die for us while we were still sinners.', 'love', 'NLT'),
('Zephaniah 3:17', 'For the LORD your God is living among you. He is a mighty savior. He will take delight in you with gladness. With his love, he will calm all your fears. He will rejoice over you with joyful songs.', 'love', 'NLT'),
('Mark 12:30-31', 'And you must love the LORD your God with all your heart, all your soul, all your mind, and all your strength. The second is equally important: ''Love your neighbor as yourself.'' No other commandment is greater than these.', 'love', 'NLT'),
('John 13:34', 'So now I am giving you a new commandment: Love each other. Just as I have loved you, you should love each other.', 'love', 'NLT'),
('Psalm 86:15', 'But you, O Lord, are a God of compassion and mercy, slow to get angry and filled with unfailing love and faithfulness.', 'love', 'NLT'),

-- GUIDANCE (18 verses)
('Proverbs 3:5-6', 'Trust in the LORD with all your heart; do not depend on your own understanding. Seek his will in all you do, and he will show you which path to take.', 'guidance', 'NLT'),
('Psalm 32:8', 'The LORD says, "I will guide you along the best pathway for your life. I will advise you and watch over you."', 'guidance', 'NLT'),
('Psalm 119:105', 'Your word is a lamp to guide my feet and a light for my path.', 'guidance', 'NLT'),
('Isaiah 30:21', 'Your own ears will hear him. Right behind you a voice will say, "This is the way you should go," whether to the right or to the left.', 'guidance', 'NLT'),
('Psalm 37:23', 'The LORD directs the steps of the godly. He delights in every detail of their lives.', 'guidance', 'NLT'),
('Proverbs 16:9', 'We can make our plans, but the LORD determines our steps.', 'guidance', 'NLT'),
('Psalm 48:14', 'For that is what God is like. He is our God forever and ever, and he will guide us until we die.', 'guidance', 'NLT'),
('Isaiah 58:11', 'The LORD will guide you continually, giving you water when you are dry and restoring your strength. You will be like a well-watered garden, like an ever-flowing spring.', 'guidance', 'NLT'),
('John 16:13', 'When the Spirit of truth comes, he will guide you into all truth.', 'guidance', 'NLT'),
('Psalm 25:9', 'He leads the humble in doing right, teaching them his way.', 'guidance', 'NLT'),
('Proverbs 4:11', 'I will teach you wisdom''s ways and lead you in straight paths.', 'guidance', 'NLT'),
('Psalm 73:24', 'You guide me with your counsel, leading me to a glorious destiny.', 'guidance', 'NLT'),
('Psalm 143:10', 'Teach me to do your will, for you are my God. May your gracious Spirit lead me forward on a firm footing.', 'guidance', 'NLT'),
('Isaiah 42:16', 'I will lead blind Israel down a new path, guiding them along an unfamiliar way. I will brighten the darkness before them and smooth out the road ahead of them.', 'guidance', 'NLT'),
('Psalm 23:2-3', 'He lets me rest in green meadows; he leads me beside peaceful streams. He renews my strength. He guides me along right paths, bringing honor to his name.', 'guidance', 'NLT'),
('Proverbs 16:3', 'Commit your actions to the LORD, and your plans will succeed.', 'guidance', 'NLT'),
('Psalm 25:4-5', 'Show me the right path, O LORD; point out the road for me to follow. Lead me by your truth and teach me, for you are the God who saves me. All day long I put my hope in you.', 'guidance', 'NLT'),
('Romans 8:14', 'For all who are led by the Spirit of God are children of God.', 'guidance', 'NLT'),

