('Psalm 32:7', 'For you are my hiding place; you protect me from trouble. You surround me with songs of victory.', 'protection', 'NLT'),
('Proverbs 18:10', 'The name of the LORD is a strong fortress; the godly run to him and are safe.', 'protection', 'NLT'),
('Psalm 46:1', 'God is our refuge and strength, always ready to help in times of trouble.', 'protection', 'NLT'),
